# owner: platform
"""Plain-text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from datetime import date


def check_owner(student: Student, marks: List[Mark]):
    """Refuse marks that belong to someone else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )


def absent_days(marks: List[Mark]) -> List[date]:
    """Distinct absent dates, oldest first."""
    found = {
        mark.day
        for mark in marks
        if mark.status == "absent"
    }
    return sorted(found)


def compose(student: Student, days: List[date]) -> str:
    """Write the notice text."""
    if not days:
        raise ValueError("no absences to report")
    name = f"{student.first_name} {student.last_name}"
    unit = "day" if len(days) == 1 else "days"
    dates = ", ".join(item.isoformat() for item in days)
    return f"{name} missed {len(days)} {unit}: {dates}."


def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice with student, days missed, dates."""
    marks = list(marks)
    check_owner(student, marks)
    return compose(student, absent_days(marks))
